-- Restaurant Management System schema (MySQL 8 / MariaDB 10.4+, InnoDB)
CREATE DATABASE IF NOT EXISTS restaurant_management_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restaurant_management_system;

CREATE TABLE IF NOT EXISTS roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, label VARCHAR(80) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS role_permissions (
  role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY (role_id, permission_id),
  FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL, role_id INT UNSIGNED NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1,
  last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, ip VARCHAR(45) NOT NULL, attempted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (email, ip, attempted_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (key_name VARCHAR(80) PRIMARY KEY, value_text TEXT NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, sort_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_items (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, description TEXT NULL,
  image_path VARCHAR(255) NULL, base_price DECIMAL(10,2) NOT NULL, prep_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10,
  is_available TINYINT(1) NOT NULL DEFAULT 1, is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX (category_id, is_active), FOREIGN KEY (category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_item_variants (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu_item_id INT UNSIGNED NOT NULL, name VARCHAR(80) NOT NULL, price_delta DECIMAL(10,2) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY (menu_item_id) REFERENCES menu_items(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS modifier_groups (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, min_select TINYINT UNSIGNED NOT NULL DEFAULT 0, max_select TINYINT UNSIGNED NOT NULL DEFAULT 5, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS modifiers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY (group_id) REFERENCES modifier_groups(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menu_item_modifier_groups (menu_item_id INT UNSIGNED NOT NULL, group_id INT UNSIGNED NOT NULL, PRIMARY KEY (menu_item_id, group_id), FOREIGN KEY (menu_item_id) REFERENCES menu_items(id), FOREIGN KEY (group_id) REFERENCES modifier_groups(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS dining_tables (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, number VARCHAR(20) NOT NULL UNIQUE, section VARCHAR(60) NULL, capacity SMALLINT UNSIGNED NOT NULL DEFAULT 4,
  status ENUM('available','occupied','reserved','cleaning','out_of_service') NOT NULL DEFAULT 'available', is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(30) NULL, email VARCHAR(190) NULL, address VARCHAR(255) NULL, notes TEXT NULL, source VARCHAR(10) NOT NULL DEFAULT 'pos', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (phone)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS orders (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(30) NOT NULL UNIQUE, idempotency_key VARCHAR(64) NULL UNIQUE,
  order_type ENUM('dine_in','takeaway','delivery') NOT NULL,
  status ENUM('pending','accepted','preparing','ready','served','completed','cancelled') NOT NULL DEFAULT 'pending',
  payment_status ENUM('unpaid','partially_paid','paid','partially_refunded','refunded') NOT NULL DEFAULT 'unpaid',
  table_id INT UNSIGNED NULL, customer_id INT UNSIGNED NULL, cashier_id INT UNSIGNED NULL,
  delivery_address VARCHAR(255) NULL, notes VARCHAR(500) NULL,
  subtotal DECIMAL(12,2) NOT NULL, discount_total DECIMAL(12,2) NOT NULL DEFAULT 0, tax_total DECIMAL(12,2) NOT NULL DEFAULT 0,
  service_charge DECIMAL(12,2) NOT NULL DEFAULT 0, delivery_charge DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL,
  paid_total DECIMAL(12,2) NOT NULL DEFAULT 0, refunded_total DECIMAL(12,2) NOT NULL DEFAULT 0, stock_deducted TINYINT(1) NOT NULL DEFAULT 0,
  source VARCHAR(10) NOT NULL DEFAULT 'pos', public_token CHAR(32) NULL UNIQUE, currency_code CHAR(3) NULL, exchange_rate DECIMAL(18,6) NOT NULL DEFAULT 1, payment_method_pref VARCHAR(20) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX (status), INDEX (payment_status), INDEX (created_at), INDEX (table_id),
  FOREIGN KEY (table_id) REFERENCES dining_tables(id), FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (cashier_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, menu_item_id INT UNSIGNED NOT NULL, variant_id INT UNSIGNED NULL,
  item_name VARCHAR(150) NOT NULL, variant_name VARCHAR(80) NULL, unit_price DECIMAL(10,2) NOT NULL, quantity SMALLINT UNSIGNED NOT NULL, line_total DECIMAL(12,2) NOT NULL, notes VARCHAR(255) NULL,
  INDEX (order_id), FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (menu_item_id) REFERENCES menu_items(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_item_modifiers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_item_id BIGINT UNSIGNED NOT NULL, modifier_id INT UNSIGNED NOT NULL, name VARCHAR(100) NOT NULL, price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_item_id) REFERENCES order_items(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, from_status VARCHAR(20) NULL, to_status VARCHAR(20) NOT NULL, changed_by INT UNSIGNED NULL, note VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (order_id), FOREIGN KEY (order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_counters (day DATE PRIMARY KEY, last_number INT UNSIGNED NOT NULL) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS payments (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method VARCHAR(30) NOT NULL, amount DECIMAL(12,2) NOT NULL,
  tendered DECIMAL(12,2) NULL, change_given DECIMAL(12,2) NULL, reference VARCHAR(100) NULL, idempotency_key VARCHAR(64) NULL UNIQUE,
  received_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (order_id), INDEX (created_at),
  FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (received_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, reason VARCHAR(255) NOT NULL, refunded_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (order_id), INDEX (created_at), FOREIGN KEY (order_id) REFERENCES orders(id), FOREIGN KEY (refunded_by) REFERENCES users(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ingredients (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, unit VARCHAR(20) NOT NULL, cost_per_unit DECIMAL(12,4) NOT NULL DEFAULT 0,
  min_stock DECIMAL(14,4) NOT NULL DEFAULT 0, quantity_on_hand DECIMAL(14,4) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recipe_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu_item_id INT UNSIGNED NOT NULL, ingredient_id INT UNSIGNED NOT NULL, quantity DECIMAL(14,4) NOT NULL,
  UNIQUE (menu_item_id, ingredient_id), FOREIGN KEY (menu_item_id) REFERENCES menu_items(id), FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_movements (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ingredient_id INT UNSIGNED NOT NULL,
  movement_type ENUM('opening','sale','adjustment','wastage','spoilage','return','purchase') NOT NULL, quantity DECIMAL(14,4) NOT NULL, balance_after DECIMAL(14,4) NOT NULL,
  reason VARCHAR(255) NOT NULL, reference_type VARCHAR(30) NULL, reference_id BIGINT UNSIGNED NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_ref (reference_type, reference_id, ingredient_id, movement_type), INDEX (ingredient_id, created_at),
  FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS suppliers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, contact_name VARCHAR(120) NULL, phone VARCHAR(30) NULL, email VARCHAR(190) NULL, address VARCHAR(255) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category VARCHAR(80) NOT NULL, amount DECIMAL(12,2) NOT NULL, expense_date DATE NOT NULL, description VARCHAR(255) NULL, payment_method VARCHAR(30) NOT NULL DEFAULT 'cash', vendor VARCHAR(120) NULL,
  created_by INT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, INDEX (expense_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type VARCHAR(30) NOT NULL, message VARCHAR(255) NOT NULL, dedupe_key VARCHAR(80) NULL UNIQUE, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (is_read, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(60) NOT NULL, entity VARCHAR(40) NULL, entity_id VARCHAR(40) NULL, summary VARCHAR(500) NULL, ip VARCHAR(45) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (created_at), INDEX (action)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS currencies (code CHAR(3) PRIMARY KEY, name VARCHAR(60) NOT NULL, symbol VARCHAR(8) NOT NULL, rate_to_base DECIMAL(18,6) NOT NULL DEFAULT 1, decimals TINYINT UNSIGNED NOT NULL DEFAULT 2, is_active TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB;
